import os
import sqlite3
import datetime
from functools import wraps

import jwt
from flask import Flask, request, jsonify, g
from werkzeug.security import generate_password_hash, check_password_hash

APP_SECRET = os.environ.get("APP_SECRET", "dev-secret-change-me")
DB_PATH = "db.sqlite3"

app = Flask(__name__)
app.config["SECRET_KEY"] = APP_SECRET


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                secret TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(user_id),
                FOREIGN KEY(user_id) REFERENCES users(id)
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def create_token(user_id, username):
    payload = {
        "sub": str(user_id),
        "username": username,
        "iat": datetime.datetime.now(datetime.timezone.utc),
        "exp": datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=24),
    }
    return jwt.encode(payload, APP_SECRET, algorithm="HS256")


def decode_token(token):
    return jwt.decode(token, APP_SECRET, algorithms=["HS256"])


def auth_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return jsonify({"message": "Invalid authentication token"}), 401
        token = auth_header[len("Bearer "):].strip()
        if not token:
            return jsonify({"message": "Invalid authentication token"}), 401
        try:
            payload = decode_token(token)
        except jwt.ExpiredSignatureError:
            return jsonify({"message": "Invalid authentication token"}), 401
        except jwt.InvalidTokenError:
            return jsonify({"message": "Invalid authentication token"}), 401
        g.user_id = int(payload["sub"])
        g.username = payload.get("username")
        return f(*args, **kwargs)

    return wrapper


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    email = data.get("email")
    username = data.get("username")
    password = data.get("password")

    if not email or not username or not password:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    if not isinstance(email, str) or not isinstance(username, str) or not isinstance(password, str):
        return jsonify({"message": "Email already in use or invalid data"}), 400

    email = email.strip()
    username = username.strip()

    if "@" not in email or len(email) < 3 or not username or len(password) < 1:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    db = get_db()
    try:
        password_hash = generate_password_hash(password)
        db.execute(
            "INSERT INTO users (email, username, password_hash) VALUES (?, ?, ?)",
            (email, username, password_hash),
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    return jsonify({"message": "Registration successful"}), 201


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    email = data.get("email")
    password = data.get("password")

    if not email or not password:
        return jsonify({"message": "Invalid email or password"}), 401

    db = get_db()
    row = db.execute(
        "SELECT id, username, password_hash FROM users WHERE email = ?", (email,)
    ).fetchone()

    if row is None or not check_password_hash(row["password_hash"], password):
        return jsonify({"message": "Invalid email or password"}), 401

    token = create_token(row["id"], row["username"])
    return jsonify({"token": token, "message": "Login successful"}), 200


@app.route("/set_secret", methods=["POST"])
@auth_required
def set_secret():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    secret = data.get("secret")

    if not username or secret is None:
        return jsonify({"message": "Invalid authentication token"}), 401

    if username != g.username:
        return jsonify({"message": "Invalid authentication token"}), 401

    if not isinstance(secret, str):
        return jsonify({"message": "Invalid authentication token"}), 401

    db = get_db()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()
    db.execute(
        """
        INSERT INTO secrets (user_id, secret, updated_at) VALUES (?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET secret = excluded.secret, updated_at = excluded.updated_at
        """,
        (g.user_id, secret, now),
    )
    db.commit()

    return jsonify({"message": "Secret has been set successfully"}), 200


@app.route("/get_secret", methods=["GET"])
@auth_required
def get_secret():
    username = request.args.get("username")

    if not username:
        return jsonify({"message": "Invalid authentication token"}), 401

    if username != g.username:
        return jsonify({"message": "Invalid authentication token"}), 401

